using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class JKRowling
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Nothing is more unnerving to the truly conventional than the unashamed misfit!", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Depression is the most unpleasant thing I have ever experienced. [...] It is that absence of being able to envisage that you will ever be cheerful again. The absence of hope. That very deadened feeling, which is so very different from feeling sad. Sad hurts but it's a healthy feeling. It's a necessary thing to feel. Depression is very different.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I've never set out to teach anyone anything. It's been more of an expression of my views and feelings than sitting down and deciding \"What is today's message?\"", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The fame thing is interesting because I never wanted to be famous, and I never dreamt I would be famous.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I think that it's a very healthy message to pass on to younger people that you should question authority and you should not assume that the establishment or the press tells you all of the truth.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Now, I am not going to stand here and tell you that failure is fun. That period of my life was a dark one, and I had no idea that there was going to be what the press has since represented as a kind of fairy tale resolution. I had no idea then how far the tunnel extended, and for a long time, any light at the end of it was a hope rather than a reality.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "So why do I talk about the benefits of failure? Simply because failure meant a stripping away of the inessential. I stopped pretending to myself that I was anything other than what I was, and began to direct all my energy into finishing the only work that mattered to me. Had I really succeeded at anything else, I might never have found the determination to succeed in the one arena I believed I truly belonged. I was set free, because my greatest fear had been realised, and I was still alive, and I still had a daughter whom I adored, and I had an old typewriter and a big idea. And so rock bottom became the solid foundation on which I rebuilt my life.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "It is impossible to live without failing at something, unless you live so cautiously that you might as well not have lived at all – in which case, you fail by default.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Imagination is not only the uniquely human capacity to envision that which is not, and therefore the fount of all invention and innovation. In its arguably most transformative and revelatory capacity, it is the power that enables us to empathise with humans whose experiences we have never shared.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Unlike any other creature on this planet, humans can learn and understand, without having experienced. They can think themselves into other people’s places.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "What is more, those who choose not to empathize enable real monsters; for without ever committing an act of outright evil ourselves, we collude with it, through our own apathy.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "What we achieve inwardly will change outer reality.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "We do not need magic to transform our world. We carry all the power we need inside ourselves already. We have the power to imagine better.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The Potter books in general are a prolonged argument for tolerance, a prolonged plea for an end to bigotry, and I think it's one of the reasons that some people don't like the books, but I think that it's a very healthy message to pass on to younger people that you should question authority and you should not assume that the establishment or the press tells you all of the truth.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "No story lives unless someone wants to listen. The stories we love best do live in us forever. So, whether you come back by page or by the big screen, Hogwarts will always be there to welcome you home.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The world is full of wonderful things you haven’t seen yet. Don’t ever give up on the chance of seeing them.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "How horrible. Voldemort was nowhere near as bad.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I mean, is ‘fat’ really the worst thing a human being can be? Is ‘fat’ worse than ‘vindictive’, ‘jealous’, ‘shallow’, ‘vain’, ‘boring’ or ‘cruel’?", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I don't think I've ever wanted magic more.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Dress however you please. Call yourself whatever you like. Sleep with any consenting adult who’ll have you. Live your best life in peace and security. But force women out of their jobs for stating that sex is real? #IStandWithMaya #ThisIsNotADrill", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "If sex isn't real, there's no same-sex attraction. If sex isn't real, the lived reality of women globally is erased. I know and love trans people, but erasing the concept of sex removes the ability of many to meaningfully discuss their lives. It isn't hate to speak the truth.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Many, myself included, believe we are watching a new kind of conversion therapy for young gay people, who are being set on a lifelong path of medicalisation that may result in the loss of their fertility and/or full sexual function.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The long-term health risks of cross-sex hormones have been now been tracked over a lengthy period. These side-effects are often minimised or denied by trans activists.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "What I didn't expect in the aftermath of my cancellation was the avalanche of emails and letters that came showering down upon me, the overwhelming majority of which were positive, grateful and supportive.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Ironically, radical feminists aren't even trans-exclusionary — they include trans men in their feminism, because they were born women.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I'm concerned about the huge explosion in young women wishing to transition and also about the increasing numbers who seem to be detransitioning (returning to their original sex), because they regret taking steps that have, in some cases, altered their bodies irrevocably, and taken away their fertility.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The current explosion of trans activism is urging a removal of almost all the robust systems through which candidates for sex reassignment were once required to pass. A man who intends to have no surgery and take no hormones may now secure himself a Gender Recognition Certificate and be a woman in the sight of the law.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "We're living through the most misogynistic period I've experienced. Never have I seen women denigrated and dehumanised to the extent they are now.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Everywhere, women are being told to shut up and sit down, or else.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I've read all the arguments about femaleness not residing in the sexed body, and the assertions that biological women don't have common experiences, and I find them, too, deeply misogynistic and regressive.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "It isn't enough for women to be trans allies. Women must accept and admit that there is no material difference between trans women and themselves.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "'Woman' is not a costume. 'Woman' is not an idea in a man's head. 'Woman' is not a pink brain, a liking for Jimmy Choos or any of the other sexist ideas now somehow touted as progressive. Moreover, the 'inclusive' language that calls female people 'menstruators' and 'people with vulvas' strikes many women as dehumanising and demeaning.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "If you could come inside my head and understand what I feel when I read about a trans woman dying at the hands of a violent man, you'd find solidarity and kinship.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Trans people need and deserve protection. Like women, they're most likely to be killed by sexual partners.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I want trans women to be safe. At the same time, I do not want to make natal girls and women less safe.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I spoke up about the importance of sex and have been paying the price ever since. I was transphobic, I was a cunt, a bitch, a TERF, I deserved cancelling, punching and death.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "It would be so much easier to tweet the approved hashtags — because of course trans rights are human rights and of course trans lives matter — scoop up the woke cookies and bask in a virtue-signalling afterglow. There's joy, relief and safety in conformity.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I refuse to bow down to a movement that I believe is doing demonstrable harm in seeking to erode 'woman' as a political and biological class and offering cover to predators like few before it.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "None of the gender critical women I've talked to hates trans people; on the contrary. Many of them became interested in this issue in the first place out of concern for trans youth, and they're hugely sympathetic towards trans adults who simply want to live their lives, but who're facing a backlash for a brand of activism they don't endorse.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The last thing I want to say is this. I haven't written this essay in the hope that anybody will get out a violin for me, not even a teeny-weeny one. I'm extraordinarily fortunate; I'm a survivor, certainly not a victim.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I never forget that inner complexity when I'm creating a fictional character and I certainly never forget it when it comes to trans people.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "All I'm asking — all I want — is for similar empathy, similar understanding, to be extended to the many millions of women whose sole crime is wanting their concerns to be heard without receiving threats and abuse.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "They should have reflected on the fact that I've now received so many death threats I could paper the house with them, and I haven't stopped speaking out. Perhaps, and I'm just throwing this out there, the best way to prove your movement isn't a threat to women, is to stop stalking, harassing and threatening us.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "War is Peace. Freedom is Slavery. Ignorance is Strength. The Penised Individual Who Raped You Is a Woman.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Using the words 'sex' and 'gender' interchangeably obscures the central issue of this debate.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The law Nicola Sturgeon is trying to pass in Scotland will harm the most vulnerable women in society — those seeking help after male violence/rape and incarcerated women.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Critiques of Western cancel culture are possibly not best made by those currently slaughtering civilians for the crime of resistance, or who jail and poison their critics. #IStandWithUkraine", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "A strange new form of temporary blindness has broken out among Scottish politicians. None of them could read placards calling for violence against women while standing inches away from them, yet they were instantly cured when photos of them posing with the signs hit the press.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Never forget, Sturgeon, her government and supporters have insisted that it is ludicrous to imagine anyone would dress in women's clothes to get access to vulnerable women and girls. Wouldn't happen. Everyone is who they say they are. To question this is hate.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "You said rapists should be transferred to women's prisons if they self-identify as women. Given that you're one of the biggest reasons many women on the Left no longer trust Labour to defend their rights, do you stand by these comments?", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I've looked around and realised that it has to be someone who can take the hit. And it has to be me. I can afford it.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "This has never been about trans rights. This is about women’s rights and activists' demands to dismantle those rights.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I have nothing but profound sympathy for trans women who have experienced male violence. I want trans people to be safe. I just don't want women and girls to be any less safe.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The pushback is often, \"You are wealthy. You can afford security. You haven't been silenced.\" All true. But I think that misses the point. The attempt to intimidate and silence me is meant to serve as a warning to other women [with similar views who may also wish to speak out].", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I do not walk around my house thinking about my legacy. What a pompous way to live your life, walking around thinking, \"What will my legacy be?\"", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "There is a huge appeal, and I try to show this in the Potter books, to black and white thinking. It's the easiest place to be and in many ways it's the safest place to be. If you take an all-or-nothing position on anything, you will definitely find comrades, you will easily find a community. \"I’ve sworn allegiance to this one simple idea.\"", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "What I've tried to show in the Potter books, and what I feel strongly myself, is that we should mistrust ourselves most when we are certain.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Book burners, by definition, have placed themselves across a line of rational debate. There is no book on this planet that I would burn, including books that I do think are damaging. Burning, to me, is the last resort of people who cannot argue.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The marriage [to Jorge Arantes] had turned very violent and very controlling. He was searching my handbag every time I came home and I didn’t have a key to my own front door.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "That manuscript meant so much to me and it was the thing that I prioritised saving. The only thing I prioritised beyond that was my daughter but at that point she was still inside me so she was as safe as she can be in that situation.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "There is something about a mass of human beings. There's always an edge in a crowd. Always.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "[Something] I explore in the Potter books [is that] a sense of righteousness is not incompatible with doing terrible things. You know, most of the people in movements that we consider hugely abhorrent, many many many of the people involved in those movements understood themselves to be on the side of righteousness. Believed they were doing the right thing. Felt themselves justified in what they were doing.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "And I think you could not have misunderstood me more profoundly.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "I'm sick of this s---. This is not a woman. These are #NotOurCrimes.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Crime statistics are rendered useless if violent and sexual attacks committed by men are recorded as female crimes. Activists are already clamouring for this sadistic killer to be incarcerated in a women’s prison.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Ideologically driven misinformation is not journalism.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "When I've asked what the lack of female-only spaces would mean for women of certain faith groups, or survivors of sexual violence, the response is an almighty shrug. Over and again I've heard \"no trans person has ever harmed a woman or a girl in a female space\", the speakers' consciences apparently untroubled by the fact that they are parroting an easily disprovable lie, because there's ample evidence that men claiming a female identity have committed sexual offences, acts of violence and voyeurism, both inside women's spaces and without.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "If a system relies on an unfalsifiable sense of self rather than sex, it's impossible to keep bad faith actors out.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Kemi Badenoch and I might not agree on a lot, but how often are male politicians called \"spiteful\"? And what's the issue with her manner? Did she fail in womanly sweetness, kindness and deference?", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Badenoch is also minister for women and equalities. Thanks once again for highlighting Labour's complacency and indifference towards the rights of half the electorate.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Rosie Duffield and I share more than the occasional meal and a fairly sweary WhatsApp thread. Last month, a man received a suspended prison sentence for sending both of us death threats. Rosie was to be taken out with a gun; I was to be beaten to death with a hammer.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The level of threats Rosie has received is such that she's had to hire personal security and was recently advised not to conduct in-person hustings.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Is this what Keir Starmer meant, when he talked about toxic, divided debate? A female MP in his own party being intimidated and harassed?", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "The impression given by Starmer at Thursday’s debate was that there had been something unkind, something toxic, something hard line in Rosie’s words, even though almost identical words had sounded perfectly reasonable when spoken by Blair.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Like other people who've never experienced adult life uncushioned by wealth and fame, Emma has so little experience of real life she's ignorant of how ignorant she is.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Adults can't expect to cosy up to an activist movement that regularly calls for a friend's assassination, then assert their right to the former friend's love, as though the friend was in fact their mother.", Author = "J. K. Rowling" },
            new Quote { Id = "https://en.wikiquote.org/wiki/J._K._Rowling", Text = "Emma’s 'all witches' speech was a turning point for me, but it had a postscript that hurt far more than the speech itself. Emma asked someone to pass on a handwritten note from her to me, which contained the single sentence: 'I'm so sorry for what you're going through.' She has my phone number.", Author = "J. K. Rowling" },
        };
    }
}